function showGuide(){modal('守住最后一条底线','像素地牢 / 单机 / Roguelite',`<div class="guide-text"><p><strong>左右移动，自动向上投掷。</strong><br>A / D 或方向键移动；空格施放角色技能；P / Esc 暂停。手机可按方向按钮，也可以在战场拖动。</p><p><strong>敌人到底线就会伤你。</strong><br>红色投射物和预警区域也会造成伤害；拾取落下的绿色经验与金币，升级选择三选一。后期升级需要更多经验；所有被动上限 4 层，满层退出奖励池。</p><p><strong>3 把武器，4 件装备。</strong><br>相同武器升级至 5 级，新武器满槽须替换；装备分五种品质，随机词条叠加，史诗与传说额外附带触发机制。装备自动入背包，换装时旧装备保留；可以按品质或套装排序，再按部位筛选。</p><p><strong>金币和诅咒，是有代价的力量。</strong><br>金币流靠持币增伤；花掉金币意味着失去部分加成。每层诅咒让敌人生命 +8%，伤害 +4.5%；装备诅咒随卸下解除。</p><p><strong>12 层远征，无尽模式继续挑战。</strong><br>每层五个房间：选择路线、精英、商店、事件和锻造。第 12 层是终章双 Boss，无尽第 20、28 层继续双 Boss；第 9 层起有三阶段异变。悬赏每层可接一项，金币用于强化、觉醒或重铸。失败和胜利都带回余烬，可解锁角色与工坊成长。</p><p><strong>系列、套装与家园。</strong><br>同系列不同部位激活 2 / 3 / 4 件效果。获得装备后，同系列抽取权重稍微增加；替换装备时会显示套装得失。击杀和 Boss 结算带回建材，在营地家园建设建筑、准备下一局补给、领取委托。</p><p><strong>离线安装。</strong><br>在线打开一次完成缓存，即可安装后离线游玩。更新需主动点击，远征期间不会强制刷新。</p></div>`);}
function settle(){if(!run||settled)return;settled=true;const r=run;resultEmbers=6+r.floor*2+Math.floor(r.kills/8)+r.bossKills*12+(r.phase==='victory'?80:0);const timber=expeditionTimber(r.floor,r.kills,r.bossKills);save.home.timber=Math.min(1e9,save.home.timber+timber);save.essence+=resultEmbers;save.stats.runs++;save.stats.kills+=r.kills;save.stats.bosses+=r.bossKills;save.stats.bestFloor=Math.max(save.stats.bestFloor,r.floor);save.stats.gold+=r.totalGold;if(r.phase==='victory')save.stats.wins++;save.seen=[...new Set([...save.seen,...r.seen])];persist();screen='results';destroyGame();
 app.innerHTML=header()+`<main class="results"><span class="eyebrow">${r.phase==='victory'?'远征通关':'余烬仍在，继续出发'}</span><div>${pixelIcon(r.hero.color,'hero',94)}</div><h1>${r.phase==='victory'?'深渊，已被你洞穿。':'这一次，止步于此。'}</h1><p>${r.hero.name} · ${regionName(r.floor)} · 活过 ${Math.floor(r.time/60)} 分 ${Math.floor(r.time%60)} 秒</p><div class="result-stats"><div><strong>${r.floor}</strong><span>到达层数</span></div><div><strong>${r.kills}</strong><span>击杀</span></div><div><strong>${r.level}</strong><span>最终等级</span></div><div><strong>${r.bossKills}</strong><span>守层者</span></div></div><div class="essence-reward">✧ +${resultEmbers} 余烬 <span class="muted">/ 持有 ${save.essence}</span></div><p class="home-reward">▥ +${timber} 建材 · 已送回家园</p><p>余烬已保存。死亡带走装备，却带不走你学会的东西。</p><div class="build-tags">${r.weapons.map(w=>`<span>${WEAPONS.find(x=>x.id===w.id)!.name} LV.${w.level}</span>`).join('')}${Object.entries(r.passives).slice(0,8).map(([id,n])=>`<span>${PASSIVES.find(p=>p.id===id)!.name} ×${n}</span>`).join('')}</div><div class="overlay-actions"><button class="primary" id="again">再下一次 →</button><button id="back-menu">选择角色 / 解锁</button><button id="result-workshop">余烬工坊</button><button id="result-home">返回家园</button></div><p class="seed-info">种子 ${r.rng.state>>>0} · 远征 #${save.stats.runs}</p></main>`;bindHeader();click('again',startRun);click('back-menu',showMenu);click('result-home',renderHome);click('result-workshop',()=>{screen='workshop';renderWorkshop();});
}
function renderArchive(){const tabs=[['weapons','武器',WEAPONS],['passives','被动',PASSIVES],['equipment','装备',EQUIPMENT],['enemies','敌人',ENEMIES],['bosses','守层者',BOSSES],['events','事件',EVENTS]] as const;const current=tabs.find(t=>t[0]===archiveTab)!;
 app.innerHTML=header()+`<main class="full-page"><div class="page-title"><div><span class="eyebrow">发现与记录</span><h2>深渊图鉴</h2></div><button id="archive-back">返回营地</button></div><div class="archive-tabs">${tabs.map(([id,label,data])=>`<button data-tab="${id}" class="small ${id===archiveTab?'selected':''}">${label} ${data.length}</button>`).join('')}<button id="archive-sets" class="small">套装指南 8</button></div><div class="archive-search"><input id="archive-search" type="search" placeholder="搜索名称、效果或机制" aria-label="搜索图鉴"><span id="archive-count">${current[2].length} 项</span></div><div class="archive-grid">${current[2].map(item=>{const seen=save.seen.includes(archiveTab==='events'?'event:'+item.id:item.id),color='color'in item?item.color:'#b79cd7',desc='desc'in item?item.desc:'text'in item?item.text:'';return`<article data-search="${esc(item.name+' '+desc+('tag'in item?' '+TAG_NAMES[item.tag]:'')+('set'in item?' '+(setById(item.set)?.name||''):''))}" class="archive-card ${seen?'':'unseen'}">${archiveTab==='weapons'||archiveTab==='equipment'||archiveTab==='passives'?`<button class="icon-inspect" data-art-kind="${archiveTab==='weapons'?'weapon':archiveTab==='equipment'?'equipment':'passive'}" data-art-id="${item.id}" aria-label="查看${item.name}图标">${itemIcon(archiveTab==='weapons'?'weapon':archiveTab==='equipment'?'equipment':'passive',item.id,52)}</button>`:pixelIcon(color,archiveTab==='bosses'?'boss':archiveTab==='enemies'?'enemy':'gear',40,item.id)}<div><h3>${item.name} ${seen?'<span class="accent">·</span>':'<small class="muted">未发现</small>'}</h3><p>${desc}</p>${'tag'in item?`<span class="pill">${TAG_NAMES[item.tag]}</span>`:''}${'set'in item?`<span class="set-chip">${setById(item.set)?.name||''}</span>`:''}</div></article>`;}).join('')}</div></main>`;bindHeader();bindArtworkButtons();click('archive-back',showMenu);click('archive-sets',()=>modal('八大套装',familyNote,setCards({},true)));document.getElementById('archive-search')!.addEventListener('input',event=>{const q=(event.target as HTMLInputElement).value.trim().toLowerCase();let count=0;document.querySelectorAll<HTMLElement>('[data-search]').forEach(card=>{card.hidden=!card.dataset.search!.toLowerCase().includes(q);if(!card.hidden)count++;});setText('archive-count',`${count} 项`);});document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b=>b.onclick=()=>{archiveTab=b.dataset.tab!;renderArchive();});
}
