function renderSettings(){app.innerHTML=header()+`<main class="full-page settings"><div class="page-title"><div><span class="eyebrow">冒险营地</span><h2>设置与存档</h2></div><button id="settings-back">返回营地</button></div>${settingsBody()}${updateSettings()}<div class="setting-row"><span>存档备份</span><div><button class="small" id="export-save">导出</button> <button class="small" id="import-save">导入</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></div><div class="setting-row"><span>独立应用 / 离线</span><button class="small" id="settings-install">安装应用 ↗</button></div><p class="settings-desc">存档保存在此浏览器的 localStorage。包括角色解锁、余烬、图鉴、工坊、家园、补给、设置与统计；清除浏览器数据会删除存档。换设备前请导出备份。</p><p class="settings-desc">Windows：Edge / Chrome 地址栏安装图标。Android：Chrome 菜单 → 安装应用。首次完整在线打开后可离线游玩。</p></main>`;bindHeader();click('settings-back',showMenu);bindSettings(renderSettings);click('settings-install',installApp);click('export-save',()=>{const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='knife-depths-save.json';a.click();URL.revokeObjectURL(url);toast('存档已导出');});click('import-save',()=>document.getElementById('import-file')!.click());document.getElementById('import-file')!.addEventListener('change',async event=>{const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(file.size>1000000){toast('存档文件过大');return;}try{const next=validateSave(JSON.parse(await file.text()));modal('导入存档','将替换当前设备的解锁、余烬与统计。',`<p>${next.stats.runs} 次远征 · ${next.essence} 余烬 · ${next.unlocked.length} 角色</p><div class="overlay-actions"><button class="primary" id="confirm-import">确认导入</button></div>`,()=>click('confirm-import',()=>{save=next;audio.enabled=save.settings.sound;persist();closeModal();renderSettings();toast('存档已导入');}));}catch(error){toast(error instanceof Error?error.message:'存档无法读取');}});}
