function renderUpdateState(){
 const state=updates.state,busy=state.phase==='checking'||state.phase==='downloading';
 document.querySelectorAll<HTMLElement>('[data-app-update-version]').forEach(el=>el.textContent='版本 '+APP_VERSION);
 document.querySelectorAll<HTMLElement>('[data-app-update-status]').forEach(el=>el.textContent=state.message);
 document.querySelectorAll<HTMLButtonElement>('[data-app-update]').forEach(button=>{button.disabled=busy;button.classList.toggle('update-available',updateReady);button.textContent=updateReady?'更新应用 ↻':state.phase==='downloading'?'下载中…':state.phase==='checking'?'检查中…':'检查更新';});
 const banner=document.getElementById('pwa-banner')!;
 if(!updateReady||updateDismissed){banner.innerHTML='';return;}
 banner.innerHTML='<strong>新版本已经准备好</strong>更新会保留角色、家园与设置。<br><button class="small" id="update-app">立即更新</button><button class="ghost small" id="update-later">稍后</button>';
 click('update-app',()=>void updates.apply());click('update-later',()=>{updateDismissed=true;renderUpdateState();});
}
